eval("{__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   \"default\": () => (__WEBPACK_DEFAULT_EXPORT__)\n/* harmony export */ });\n/* harmony default export */ const __WEBPACK_DEFAULT_EXPORT__ = (`\n      <section>\n        <div class=\"title__wrapper\" id=\"catering-title-1\">\n          <div class=\"title hero\">\n            <div class=\"title__container\">\n              <h2 class=\"title__heading\">OLEA CATERING</h2>\n              <p class=\"title__text\">Café classics, created for all your special occasions.</p>\n              <button class=\"primary-btn\">BROCHURE</button>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"content\">\n          <div class=\"content__container\">\n            <h3 class=\"content__heading\">FRESH BAKES AND COFFEE FOR CORPORATE AND PRIVATE EVENTS.</h3>\n            <p class=\"content__text\">If you're looking for something delicious to impress your family, guests or colleagues this season, look no further: OLEA CATERS! Choose from our catering menu, where portions are party-friendly, so you can mix pastries, cookies, cakes and pasta trays for a spread with something for everyone. If your mouth is already watering, it's time to get in touch. We'd love to help!</p>\n            <p class=\"content__text\">Whether you need catering for a corporate meeting or a casual family gathering, let Olea do the cooking so you can enjoy the occasion. Our catering menu changes seasonally and includes bite-sized versions of the pastries, brownies, cupcakes and cheesecakes you'd find in our cafés, plus a few special items we only make to order. Everything is prepared from scratch on the day, tastes great even at room temperature, and stays fresh throughout your event.</p>\n            <p class=\"content__text\">We also make celebration cakes and cupcake towers for all occasions. Please email us at catering@cafeolea.ph to discuss your requirements.</p>\n          </div>\n        </div>\n      </section>\n\n      <section>\n        <div class=\"title__wrapper\" id=\"catering-title-2\">\n          <div class=\"title\">\n            <div class=\"title__container\">\n              <h2 class=\"title__heading\">OUR FAMOUS, DUBAI CHEWY.</h2>\n              <p class=\"title__text\">Boxed, ribboned and ready for your table.</p>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"content\">\n          <div class=\"content__container\">\n            <h3 class=\"content__heading\">DUBAI CHEWY BOXES</h3>\n            <p class=\"content__text\">Please don't call it \"just a cookie\", because ours is the Dubai Chewy. It's one of the thickest, chewiest cookies you've ever tasted, baked fresh each morning with in-house pistachio cream, toasted kataifi and real dark chocolate, with no artificial flavours or preservatives. Our long-rested dough gives it that deep, caramel flavour and its signature chew.</p>\n            <p class=\"content__text\">If you've had one in our café, you know what we mean. Want them at your event? Just ask!</p>\n            <button class=\"primary-btn\">BROCHURE</button>\n            <h3 class=\"content__heading text-center mt-16\">TO ORDER YOUR CAFÉ FEAST PLEASE EMAIL US AT CATERING@CAFEOLEA.PH</h3>\n            <p class=\"content__text text-center\">Please note we can provide disposable plates and cutlery upon request only, at an extra charge.</p>\n          </div>\n        </div>\n      </section>\n`);//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///./src/components/catering.js\n\n}");

