eval("{__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   \"default\": () => (__WEBPACK_DEFAULT_EXPORT__)\n/* harmony export */ });\n/* harmony import */ var _img_cafe_olea_welcome_content_1_jpeg__WEBPACK_IMPORTED_MODULE_0__ = __webpack_require__(/*! ../img/cafe-olea-welcome-content-1.jpeg */ \"./src/img/cafe-olea-welcome-content-1.jpeg\");\n/* harmony import */ var _img_cafe_olea_welcome_content_2_jpeg__WEBPACK_IMPORTED_MODULE_1__ = __webpack_require__(/*! ../img/cafe-olea-welcome-content-2.jpeg */ \"./src/img/cafe-olea-welcome-content-2.jpeg\");\n/* harmony import */ var _img_cafe_olea_welcome_content_3_jpeg__WEBPACK_IMPORTED_MODULE_2__ = __webpack_require__(/*! ../img/cafe-olea-welcome-content-3.jpeg */ \"./src/img/cafe-olea-welcome-content-3.jpeg\");\n/* harmony import */ var _img_cafe_olea_welcome_content_4_jpeg__WEBPACK_IMPORTED_MODULE_3__ = __webpack_require__(/*! ../img/cafe-olea-welcome-content-4.jpeg */ \"./src/img/cafe-olea-welcome-content-4.jpeg\");\n\n\n\n\n\n/* harmony default export */ const __WEBPACK_DEFAULT_EXPORT__ = (`\n      <section>\n        <div class=\"title__wrapper\" id=\"welcome-title-1\">\n          <div class=\"title hero\">\n            <div class=\"title__container\">\n              <h2 class=\"title__heading\">MORE THAN COFFEE. A SANCTUARY.</h2>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"content\">\n          <div class=\"content__container\">\n            <h3 class=\"content__heading\">OLEA ISN'T JUST A CAFÉ. IT'S A SLOW MORNING.</h3>\n            <p class=\"content__text\">Which means well-pulled espresso, bakes made from scratch, and a table that's always yours for as long as you like. Right here, every day.</p>\n            <p class=\"content__text\">From our coffee bar, bakery and kitchen, we serve velvety lattes, flaky croissants, fudgy brownies, towering cheesecakes, comforting pastas and, of course, the Dubai chewy cookie we're known for.</p>\n            <p class=\"content__text\">Everything is made by hand, using the best ingredients we can find, with the patience that good food deserves. No rush, no shortcuts.</p>\n            <p class=\"content__text\">Sit by the window and watch our baristas pull shots while the ovens fill the room with butter and sugar. Come for the coffee, stay for the afternoon. A little piece of classic café culture, right here at home.</p>\n          </div>\n        </div>\n      </section>\n\n      <section>\n        <div class=\"title__wrapper\" id=\"welcome-title-2\">\n          <div class=\"title\">\n            <div class=\"title__container\">\n              <h2 class=\"title__heading\">PASTA. SPRITZ. SWEET FINISH.</h2>\n              <p class=\"title__text\">Dinner, the Olea way. From 5pm at Maginhawa. Walk-ins welcome.</p>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"content\">\n          <div class=\"content__container\">\n            <h3 class=\"content__heading\">PASTA NIGHT HAS ARRIVED.</h3>\n            <p class=\"content__text\">Our daytime café turns into an easy evening kitchen: handmade sauces, al dente pasta and plates made for sharing (or not). Start with garlic bread and marinated olives, add any iced coffee or cooler for just ₱99 with every pasta, then finish with a warm brownie or a slice of cheesecake. Now that's an evening.</p>\n            <p class=\"content__text\">Walk-ins and reservations available from 5pm at our Maginhawa flagship, Quezon City.</p>\n            <p class=\"content__text\">Takeaway and delivery are also available.</p>\n            <button class=\"primary-btn\">RESERVE</button>\n            <div class=\"content__columns\">\n              <div class=\"content__column\">\n                <img class=\"content__column-img\" src=\"${_img_cafe_olea_welcome_content_1_jpeg__WEBPACK_IMPORTED_MODULE_0__}\" alt=\"Dinner Meal\">\n              </div>\n              <div class=\"content__column\">\n                <img class=\"content__column-img\" src=\"${_img_cafe_olea_welcome_content_2_jpeg__WEBPACK_IMPORTED_MODULE_1__}\" alt=\"Pasta and Cooler\">\n              </div>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <section>\n        <div class=\"title__wrapper\" id=\"welcome-title-3\">\n          <div class=\"title\">\n            <div class=\"title__container\">\n              <h2 class=\"title__heading\">NOT JUST A COOKIE. DUBAI CHEWY.</h2>\n              <p class=\"title__text\">Baked in small batches, every single day.</p>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"content\">\n          <div class=\"content__container\">\n            <h3 class=\"content__heading\">THE COOKIE EVERYONE QUEUES FOR.</h3>\n            <p class=\"content__text\">When our Dubai chewy cookies come out of the oven, the line usually follows. Thick, soft and properly chewy, filled with pistachio cream and crisp toasted kataifi, it's the one thing our regulars never leave without. Baked fresh each morning, and when they're gone, they're gone.</p>\n            <div class=\"content__columns\">\n              <div class=\"content__column\">\n                <img class=\"content__column-img\" src=\"${_img_cafe_olea_welcome_content_3_jpeg__WEBPACK_IMPORTED_MODULE_2__}\" alt=\"Handmade Dubai Chewy\">\n                <h4 class=\"content__sub-heading\">REAL INGREDIENTS, REAL CRUNCH.</h4>\n                <p class=\"content__text\">Our pistachio cream is made in-house from roasted pistachios, white chocolate and a touch of tahini. The kataifi is toasted slowly in butter until golden, then folded in right before baking so every bite stays crisp. We use dark chocolate by the block, never chips, and finish each cookie with flaky sea salt. And once you've tried the original, ask about Dubai Bianco, Dubai Caramello and Dubai Nero.</p>\n              </div>\n              <div class=\"content__column\">\n                <img class=\"content__column-img\" src=\"${_img_cafe_olea_welcome_content_4_jpeg__WEBPACK_IMPORTED_MODULE_3__}\" alt=\"Olea Coffee Cart\">\n                <h4 class=\"content__sub-heading\">HIRE OLEA'S COFFEE CART.</h4>\n                <p class=\"content__text\">Our vintage-style espresso cart will give your wedding, launch or birthday that extra something: a barista, a short menu of hot and iced coffees, and a tray of fresh cookies for every guest. If you've had our coffee in the café, you know what we mean. To bring Olea to your event, contact us at catering@cafeolea.ph</p>\n              </div>\n            </div>\n          </div>\n        </div>\n      </section>\n\n      <section>\n        <div class=\"title__wrapper\" id=\"welcome-title-4\">\n          <div class=\"title\">\n            <div class=\"title__container\">\n              <h2 class=\"title__heading\">BUTTER. PISTACHIO. PATIENCE.</h2>\n              <p class=\"title__text\">No shortcuts. Just the Olea way.</p>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"content\">\n          <div class=\"content__container\">\n            <h3 class=\"content__heading\">WONDERING WHAT MAKES OUR COOKIES SO THICK AND CHEWY?</h3>\n            <p class=\"content__text\">It starts with three simple things: brown butter, quality chocolate and time. Our dough is mixed by hand and rested for 48 hours, which deepens the flavour, brings out the caramel notes and gives the cookie its signature chew. Our fillings and flavours change with the seasons, but every recipe follows the same rule: make it slowly, make it properly, make it worth the wait.</p>\n          </div>\n        </div>\n      </section>\n\n      <section>\n        <div class=\"title__wrapper\" id=\"welcome-title-5\">\n          <div class=\"title\">\n            <div class=\"title__container\">\n              <h2 class=\"title__heading\">A STORY IN EVERY CUP.</h2>\n            </div>\n          </div>\n        </div>\n\n        <div class=\"content\">\n          <div class=\"content__container\">\n            <h3 class=\"content__heading\">INSPIRED BY OLD CAFÉS. MADE FOR TODAY.</h3>\n            <p class=\"content__text\">Picture a quiet corner café in a European city, with marble tables, bentwood chairs, the hiss of the espresso machine and a glass case of pastries by the door. That feeling, unhurried and a little bit romantic, is where Olea began.</p>\n            <p class=\"content__text\">In 2021, two friends who had spent years collecting café memories from Rome to Vienna to Paris decided to bring that culture home. Olea takes its name from the Latin word for the olive tree, a symbol of peace, patience and things that grow slowly.</p>\n            <p class=\"content__text\">Today, with our flagship on Maginhawa Street and a second home in Tagaytay, we're proud to share that slower way of doing things with more people. More than a place to get a coffee, Olea is built on craft, comfort and a love of the everyday ritual. Pull up a chair and stay awhile, because every cup tells a story.</p>\n          </div>\n        </div>\n      </section>\n`);//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///./src/components/welcome.js\n\n}");

